const fs=require('node:fs');
const cp=require('node:child_process');
const crypto=require('node:crypto');
const assert=require('node:assert/strict');
const spec=require('./checked-update.json');
const config=require('../src-tauri/tauri.conf.json');
const repo=process.env.GITHUB_REPOSITORY;
const gh=(...args)=>cp.execFileSync('gh',args,{encoding:'utf8'});
const git=(...args)=>cp.execFileSync('git',args,{encoding:'utf8'});
const dir='update-output';
if(process.argv[2]==='prepare') {
  assert.match(spec.version,/^\d+\.\d+\.\d+(?:-[a-z0-9.]+)?$/);
  assert.equal(config.version,spec.version);
  assert.equal(require('../package.json').version,spec.version);
  git('merge-base','--is-ancestor',spec.source_sha,'HEAD');
  git('diff','--exit-code',spec.source_sha,'HEAD','--','src','src-tauri','tools','tests','package.json','package-lock.json');
  gh('run','watch',String(spec.run_id),'--exit-status','--interval','15');
  const run=JSON.parse(gh('run','view',String(spec.run_id),'--json','headSha,conclusion,status,workflowName'));
  assert.equal(run.headSha,spec.source_sha);assert.equal(run.status,'completed');assert.equal(run.conclusion,'success');assert.equal(run.workflowName,'Windows desktop checks');
  fs.mkdirSync(dir,{recursive:true});
  gh('run','download',String(spec.run_id),'--name','fm-player-sorter-windows','--dir',dir);
  const names=fs.readdirSync(dir).filter(n=>n.endsWith('.exe'));assert.equal(names.length,1);
  const installer=`FM_Player_Sorter_${spec.version}_x64-setup.exe`;
  if(names[0]!==installer)fs.renameSync(`${dir}/${names[0]}`,`${dir}/${installer}`);
  const bytes=fs.readFileSync(`${dir}/${installer}`);assert.equal(bytes.subarray(0,2).toString(),'MZ');assert(bytes.length>1000000);
  fs.writeFileSync(`${dir}/build.json`,JSON.stringify({installer,source_sha:spec.source_sha,run_id:spec.run_id,sha256:crypto.createHash('sha256').update(bytes).digest('hex')},null,2));
} else if(process.argv[2]==='publish') {
  const build=require('../update-output/build.json');
  const file=`${dir}/${build.installer}`;
  const bytes=fs.readFileSync(file);
  assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),build.sha256);
  const signature=fs.readFileSync(file+'.sig','utf8').trim();
  const keyText=Buffer.from(config.plugins.updater.pubkey,'base64').toString().trim().split(/\r?\n/);
  const key=Buffer.from(keyText.find(line=>!line.startsWith('untrusted comment:')),'base64');
  const publicKey=crypto.createPublicKey({key:Buffer.concat([Buffer.from('302a300506032b6570032100','hex'),key.subarray(10)]),format:'der',type:'spki'});
  const lines=Buffer.from(signature,'base64').toString().trim().split(/\r?\n/);
  const sig=Buffer.from(lines[1],'base64');assert(sig.subarray(2,10).equals(key.subarray(2,10)));
  const algorithm=sig.subarray(0,2).toString();assert(['ED','Ed'].includes(algorithm));
  const message=algorithm==='ED'?crypto.createHash('blake2b512').update(bytes).digest():bytes;
  assert(crypto.verify(null,message,publicKey,sig.subarray(10)),'Installer signature failed');
  assert(crypto.verify(null,Buffer.concat([sig.subarray(10),Buffer.from(lines[2].replace(/^trusted comment: /,''))]),publicKey,Buffer.from(lines[3],'base64')),'Trusted comment failed');
  const tag=spec.release_tag;
  const release=JSON.parse(gh('api',`repos/${repo}/releases/tags/${tag}`));
  assert(!release.draft);
  const notes=`Obsługa prowadzonego klubu (pierwsza drużyna, rezerwy i juniorzy), rankingi pozycji i ról ograniczone do własnego składu oraz osobna wyszukiwarka transferowa: cena wywoławcza, wartość, obecna płaca, kontrakt, OU i potencjał. Odczyt FM27 pozostaje eksperymentalny i wymaga sprawdzenia w uruchomionej grze.\n\nAktualna wersja: ${spec.version}. Ten release jest stałym kanałem aktualizacji istniejącej aplikacji; nazwa tagu pozostaje historyczna.\nŹródła instalatora: https://github.com/${repo}/tree/${spec.source_sha}\nPomyślne testy i kompilacja Windows: https://github.com/${repo}/actions/runs/${spec.run_id}\nAutomatyczne archiwa „Source code” odnoszą się do historycznego tagu; źródła obecnej aktualizacji wskazuje powyższy commit i plik pochodzenia.`;
  const url=`https://github.com/${repo}/releases/download/${tag}/${build.installer}`;
  const platform={signature,url};
  const manifest={version:spec.version,notes,pub_date:new Date().toISOString(),platforms:{'windows-x86_64':platform,'windows-x86_64-nsis':platform}};
  fs.writeFileSync(`${dir}/latest.json`,JSON.stringify(manifest,null,2));
  const provenance=`${dir}/update-source-${spec.version}.json`;
  fs.writeFileSync(provenance,JSON.stringify({...build,version:spec.version,source_url:`https://github.com/${repo}/tree/${spec.source_sha}`},null,2));
  fs.writeFileSync(`${dir}/notes.md`,notes);
  gh('release','upload',tag,file,file+'.sig',provenance,'--clobber');
  const assets=JSON.parse(gh('api',`repos/${repo}/releases/tags/${tag}`)).assets;
  const asset=assets.find(a=>a.name===build.installer);assert(asset&&asset.size===bytes.length);
  const current=JSON.parse(gh('api',`repos/${repo}/releases/latest`));assert.equal(current.tag_name,tag);
  // Keep the previous manifest active until the new installer and signature exist.
  gh('release','upload',tag,`${dir}/latest.json`,'--clobber');
  gh('release','edit',tag,'--title',`FM Player Sorter ${spec.version} — aktualizacje aplikacji`,'--notes-file',`${dir}/notes.md`,'--prerelease=false','--latest');
  console.log(`Published verified update ${spec.version}, source ${spec.source_sha}`);
} else {throw Error('Expected prepare or publish');}
